package dev.pocketengine.runtime;
import dev.pocketengine.core.RunControl;
import dev.pocketengine.runtime.usage.InferenceFailure;
import java.util.List;
import org.junit.Test;
import static org.junit.Assert.*;
public final class SafeModelRecoveryTest {
 private static Exception observed(InferenceFailure observation)throws Exception{var constructor=ModelGateway.GatewayException.class.getDeclaredConstructor(String.class,InferenceFailure.class);constructor.setAccessible(true);return constructor.newInstance("native observation",observation);}
 @Test public void respectsServerWaitWithoutClampingOrAcceptingAmbiguousHeaders()throws Exception{long now=System.currentTimeMillis();SafeModelRecovery policy=new SafeModelRecovery();assertEquals(-1,policy.delay(observed(InferenceFailure.http(429,List.of("31"),List.of(),now)),0,now));assertEquals(-1,policy.delay(observed(InferenceFailure.http(429,List.of("0","0"),List.of(),now)),0,now));long delay=policy.delay(observed(InferenceFailure.http(503,List.of("2"),List.of(),now)),0,now);assertEquals(2000,delay);assertEquals(-1,policy.delay(observed(InferenceFailure.http(503,List.of(),List.of(),now)),2,now));}
 @Test public void authenticationRefusalAndUnknownAreNeverTransient()throws Exception{long now=System.currentTimeMillis();SafeModelRecovery policy=new SafeModelRecovery();for(int code:List.of(400,401,403,404,402,501))assertEquals(-1,policy.delay(observed(InferenceFailure.http(code,List.of(),List.of(),now)),0,now));for(var kind:List.of(InferenceFailure.Kind.UNKNOWN,InferenceFailure.Kind.PROTOCOL,InferenceFailure.Kind.LOCAL_REFUSAL))assertEquals(-1,policy.delay(observed(InferenceFailure.local(kind,now)),0,now));}
 @Test public void cancellationWakesOriginalBackoffWithoutAnotherDispatch()throws Exception{RunControl control=new RunControl();SafeModelRecovery policy=new SafeModelRecovery();java.util.concurrent.CountDownLatch waiting=new java.util.concurrent.CountDownLatch(1);java.util.concurrent.atomic.AtomicBoolean stopped=new java.util.concurrent.atomic.AtomicBoolean();Thread thread=new Thread(()->{waiting.countDown();try{policy.waitBeforeRetry(30000,control);}catch(Exception cancelled){stopped.set(true);}});thread.start();assertTrue(waiting.await(1,java.util.concurrent.TimeUnit.SECONDS));control.cancel();thread.join(1000);assertFalse(thread.isAlive());assertTrue(stopped.get());assertEquals(30000,policy.waitedMillis());}
 @Test public void steeringEndsOnlyOriginalBackoffWithoutRefundingItsReservedAllowance()throws Exception{
  RunControl control=new RunControl();control.bindHostRun("task","run",1);SafeModelRecovery policy=new SafeModelRecovery();long revision=control.modelReplanRevision();
  java.util.concurrent.ExecutorService worker=java.util.concurrent.Executors.newSingleThreadExecutor();java.util.concurrent.CountDownLatch entered=new java.util.concurrent.CountDownLatch(1);
  try{var waiting=worker.submit(()->{entered.countDown();policy.waitBeforeRetry(30000,control,revision);return null;});assertTrue(entered.await(1,java.util.concurrent.TimeUnit.SECONDS));assertTrue(control.requestModelReplan("task","run",1));
   var stopped=assertThrows(java.util.concurrent.ExecutionException.class,()->waiting.get(1,java.util.concurrent.TimeUnit.SECONDS));assertTrue(stopped.getCause() instanceof RunControl.ModelReplanRequested);assertFalse(control.isCancelled());control.check();assertEquals(1,policy.retries());assertEquals(30000,policy.waitedMillis());
  }finally{worker.shutdownNow();assertTrue(worker.awaitTermination(2,java.util.concurrent.TimeUnit.SECONDS));}
 }
 @Test public void contextErrorUsesBoundedStrictUtf8ReaderCompatibleWithOriginalAndroidMinimum()throws Exception{var method=ModelGateway.class.getDeclaredMethod("contextLimitCode",java.io.InputStream.class);method.setAccessible(true);String exact="{\"error\":{\"code\":\"context_length_exceeded\"}}";assertEquals(true,method.invoke(null,new java.io.ByteArrayInputStream(exact.getBytes(java.nio.charset.StandardCharsets.UTF_8))));assertEquals(false,method.invoke(null,new java.io.ByteArrayInputStream((exact+" ".repeat(16385)).getBytes(java.nio.charset.StandardCharsets.UTF_8))));assertEquals(false,method.invoke(null,new java.io.ByteArrayInputStream(new byte[]{(byte)0xc3,(byte)0x28})));assertEquals(false,method.invoke(null,new java.io.ByteArrayInputStream("{\"error\":{\"message\":\"context_length_exceeded\"}}".getBytes(java.nio.charset.StandardCharsets.UTF_8))));}

 @Test public void generic429NeverBecomesTransientWithoutOriginalMachineClassification()throws Exception{long now=System.currentTimeMillis();SafeModelRecovery policy=new SafeModelRecovery();assertEquals(-1,policy.delay(observed(InferenceFailure.http(429,List.of("0"),List.of(),now)),0,now));assertTrue(policy.delay(observed(InferenceFailure.classifiedHttp(429,List.of("0"),List.of(),now,"{\"error\":{\"code\":\"rate_limit_exceeded\"}}")),0,now)>=500);}
}
